// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockTimestamp1, uint256 blockTimestamp2, uint256 blockNumber1, uint256 blockNumber2) public {
        vm.assume(blockTimestamp2 > blockTimestamp1);
        vm.assume(blockTimestamp1 > 0);
        vm.assume(blockNumber1 % 15 != 0);
        vm.assume(blockNumber2 % 15 != 0);
        address caller = address(0x1234);
        vm.deal(caller, 20 ether);

        vm.warp(blockTimestamp1);
        vm.roll(blockNumber1);
        vm.prank(caller);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        require(ok1, "First call failed");

        vm.warp(blockTimestamp2);
        vm.roll(blockNumber2);
        vm.prank(caller);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        require(ok2, "Second call failed");

        assertEq(c.pastBlockTime(), blockTimestamp2);
    }
}
